import { useState } from 'react';
import axios from 'axios';

export default function HomePage() {
  const [sentence, setSentence] = useState('');
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleRecommend = async () => {
    if (!sentence.trim()) {
      setError('Please enter a Marathi sentence before recommending.');
      setResult(null);
      return;
    }

    try {
      setError('');
      setLoading(true);
      const response = await axios.post('http://localhost:8000/api/recommend', { sentence });
      setResult(response.data);
    } catch (err) {
      const message = err.response?.data?.detail || 'Recommendation failed. Please check the backend and try again.';
      setError(message);
      setResult(null);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-100 via-slate-50 to-sky-50 py-10 px-4">
      <div className="max-w-4xl mx-auto">
        <div className="bg-white/90 backdrop-blur-md border border-slate-200 shadow-xl rounded-3xl p-10">
          <div className="text-center mb-8">
            <p className="uppercase tracking-[0.35em] text-sm text-sky-600 font-semibold mb-3">Marathi Proverbs</p>
            <h1 className="text-4xl md:text-5xl font-extrabold text-slate-900">Marathi Proverb Recommendation</h1>
            <p className="mt-4 text-slate-600 text-lg">Type a Marathi sentence and get the most relevant proverb instantly.</p>
          </div>

          <div className="grid gap-6 md:grid-cols-[1.5fr_1fr]">
            <div className="space-y-4">
              <textarea
                className="w-full min-h-[200px] border border-slate-300 rounded-3xl p-5 text-lg leading-relaxed focus:outline-none focus:ring-2 focus:ring-sky-500"
                value={sentence}
                onChange={e => setSentence(e.target.value)}
                placeholder="उदाहरण: तो अभ्यास न करता परीक्षेला गेला..."
              />

              <div className="flex flex-col sm:flex-row gap-3 sm:items-center sm:justify-between">
                <button
                  className="inline-flex items-center justify-center rounded-full bg-sky-600 px-6 py-3 text-white font-semibold shadow-lg shadow-sky-200 transition hover:bg-sky-700"
                  onClick={handleRecommend}
                  disabled={loading}
                >
                  {loading ? 'Recommending...' : 'Recommend Proverb'}
                </button>
                <p className="text-sm text-slate-500">Tip: use clear Marathi sentences for better matches.</p>
              </div>

              {error && <p className="text-red-600 font-medium">{error}</p>}
            </div>

            <div className="rounded-3xl border border-slate-200 bg-slate-50 p-6 shadow-sm">
              <h2 className="text-xl font-semibold text-slate-900 mb-4">How it works</h2>
              <ul className="space-y-3 text-slate-700">
                <li>• Enter a Marathi sentence describing a situation.</li>
                <li>• The backend uses semantic matching to select a proverb.</li>
                <li>• You get meaning, category, emotion, and confidence.</li>
              </ul>
            </div>
          </div>

          {result && (
            <div className="mt-10 rounded-3xl border border-sky-200 bg-white p-6 shadow-lg">
              <div className="flex flex-col gap-4 md:flex-row md:items-start md:justify-between">
                <div>
                  <h2 className="text-2xl font-bold text-slate-900">Recommended Proverb</h2>
                  <p className="mt-2 text-slate-600">Confidence: <span className="font-semibold text-sky-700">{result.confidence.toFixed(1)}%</span></p>
                </div>
                <div className="rounded-full bg-sky-50 px-4 py-2 text-sky-700 font-semibold">{result.category}</div>
              </div>

              <div className="mt-6 space-y-4 text-slate-700">
                <div>
                  <p className="text-sm uppercase tracking-[0.18em] text-slate-500">Proverb</p>
                  <p className="mt-2 text-2xl font-semibold text-slate-900">{result.proverb}</p>
                </div>
                <div>
                  <p className="text-sm uppercase tracking-[0.18em] text-slate-500">Meaning</p>
                  <p className="mt-2 text-lg text-slate-700">{result.meaning}</p>
                </div>
                <div>
                  <p className="text-sm uppercase tracking-[0.18em] text-slate-500">Emotion</p>
                  <p className="mt-2 text-lg text-slate-700">{result.emotion}</p>
                </div>
              </div>

              {result.top_matches?.length > 0 && (
                <div className="mt-8">
                  <h3 className="text-lg font-semibold text-slate-900 mb-3">Top Matches</h3>
                  <div className="grid gap-3">
                    {result.top_matches.map(match => (
                      <div key={match.id} className="rounded-3xl border border-slate-200 bg-slate-50 p-4">
                        <p className="font-semibold text-slate-900">{match.proverb}</p>
                        <p className="mt-2 text-sm text-slate-600">{match.meaning}</p>
                        <div className="mt-3 flex flex-wrap gap-2 text-xs text-slate-500">
                          <span className="rounded-full bg-white px-3 py-1 border border-slate-200">{match.category}</span>
                          <span className="rounded-full bg-white px-3 py-1 border border-slate-200">{match.emotion}</span>
                          <span className="rounded-full bg-white px-3 py-1 border border-slate-200">{match.confidence.toFixed(1)}%</span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
